                                               <button key={dIdx} type="button" onClick={() => { const nl = [...(formData.warnings as any[])]; const cur = nl[index].drugs || []; if (!cur.includes(d.name)) { nl[index] = { ...nl[index], drugs: [...cur, d.name] }; setFormData({ ...formData, warnings: nl }); } setWarnDrugQuery(""); setSearchingWarnDrugIndex(null); }} className={cn("w-full text-left px-4 py-2 text-[10px] hover:bg-rose-600 hover:text-white transition-colors border-b last:border-b-0 flex items-center justify-between", isDarkMode ? "border-slate-800 text-slate-300" : "border-slate-100 text-slate-700")}><span className="font-bold">💊 {d.name}</span>{d.isCYP3A4 && <span className="bg-amber-500 text-white font-extrabold px-1 py-0.5 rounded text-[8px] uppercase">CYP3A4</span>}</button>
